// AK47 rifle geometry, baked from a CAD model (AK47.obj, 26404 triangles).
//
// Baked to a script rather than loaded at runtime because the game runs as
// plain <script> tags off file://, where Chromium blocks fetch/XHR of text
// assets — an OBJLoader would need file-access flags loosened to work.
//
// The model arrived with +X toward the muzzle and +Z up; the game's rifle frame
// is +Z forward, +Y up. Baking applies the cyclic permutation x->z, y->x, z->y
// (a proper rotation, so the receiver is not mirrored), then scales and places
// it so the barrel tip and stock land on the previous rifle's z extents and the
// bore sits at y=0.02 — the muzzle anchor's height. So the mount points,
// muzzle position and every shot effect are unchanged.
//
// Regenerate with scratchpad/bake-ak47.js if the source model changes.
// Bounds after baking: min -0.054, -0.424, -0.635 / max 0.054, 0.123, 1.180
const AK47_MODEL = {
    positions: '',
    normals: '',
    index: '',
    groups: [{"start":0,"count":71862,"mat":"Iron_-_Cast"},{"start":71862,"count":7350,"mat":"Cherry"}],
};
